declarations.complete_primitive_definition:
noncomputable def conductorPrimitiveCharacter {q : ℕ}
    (χ : DirichletCharacter ℂ q) : PrimitiveCharacter χ.conductor :=
  ⟨χ.primitiveCharacter, χ.primitiveCharacter_isPrimitive⟩

def primitiveCharacterPrefixSquare (b : ℤ → ℂ) (M : ℤ) (y q : ℕ)
    (χ : PrimitiveCharacter q) : ℝ :=
  ‖∑ n ∈ Finset.Icc (M + 1) (M + y), b n * χ.1 (n : ZMod q)‖ ^ 2

def betaCoprimeAPDiscrepancy (N : Finset ℕ) (β : ℕ → ℝ) (d h b : ℕ) : ℝ :=
  (∑ n ∈ N, if n.Coprime h ∧ Nat.ModEq d n b then β n else 0) -
    coprimeMass N β (d * h) / (d.totient : ℝ)

def characterPrefixSquare {q : ℕ} (χ : DirichletCharacter ℂ q)
    (b : ℤ → ℂ) (M : ℤ) (y : ℕ) : ℝ :=
  ‖∑ n ∈ Finset.Icc (M + 1) (M + y), b n * χ (n : ZMod q)‖ ^ 2

def MediumAtom.auxSWError (d : MediumAtom) (k q b : ℕ) : ℂ :=
  (∑ n ∈ d.alphaCarrier,
    if Nat.ModEq q n b ∧ Nat.Coprime n k then d.alpha n else 0) -
  (∑ n ∈ d.alphaCarrier,
    if Nat.Coprime n (k * q) then d.alpha n else 0) / (Nat.totient q : ℂ)

def MediumAtom.transposedPairedSWError (d : MediumAtom) (k q b : ℕ) : ℂ :=
  (∑ n ∈ d.transposedAtom.betaCarrier,
    if Nat.ModEq q n b ∧ Nat.Coprime n k then d.transposedAtom.beta n else 0) -
  (∑ n ∈ d.transposedAtom.betaCarrier,
    if Nat.Coprime n (k * q) then d.transposedAtom.beta n else 0) / (Nat.totient q : ℂ)

def MediumAtom.sharedFirstFactorCoefficient (d : MediumAtom)
    (l : (ℕ × ℕ) × ℕ) : ℂ :=
  d.gamma2 l.1.1 * d.gamma3 l.1.2 * d.transposedAtom.beta l.2
